#include <stdio.h>

int main(void) {
    int a[] = {22, 12, 13, 8, 9, 20, 33, 42, 44, 38, 24, 48, 60, 58, 74, 49, 86, 53};
    int idx_max[] = {22, 48, 86};
    int idx_start[] = {0, 6, 12};
    int blocks = 3;
    int key = 38;
    int b = 0;
    int cmp_idx = 0, start = 0, end = 0;
    int found = 0, pos = -1;
    int i;
    int n = (int)(sizeof(a) / sizeof(a[0]));
    double asl_succ;
    const char *res;
    for (b = 0; b < blocks; b++) {
        if (key <= idx_max[b]) break;
    }
    cmp_idx = b + 1;
    start = idx_start[b];
    end = (b + 1 < blocks) ? idx_start[b + 1] : n;
    for (i = start; i < end; i++) {
        if (a[i] == key) { found = 1; pos = i; break; }
    }
    asl_succ = (double)(blocks + 1) / 2.0 + (double)(n / blocks + 1) / 2.0;
    res = found ? "是" : "否";
    printf("分块查找  n=%d  分块数=%d  key=%d\n", n, blocks, key);
    printf("索引比较次数=%d  命中块起点=%d  找到=%s  位置=%d\n", cmp_idx, start, res, pos);
    printf("近似 ASL(成功)=(s+1)/2+(b+1)/2=%.2f  （s=块数=%d, 块长 b=%d）\n", asl_succ, blocks, n / blocks);
    return 0;
}
